import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:intl/intl.dart';import '../../../core/providers/app_providers.dart';
class SavedScreen extends ConsumerWidget{const SavedScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final c=ref.watch(appControllerProvider);final saved=c.items('favorites'),history=c.items('reading_history');final historySorted=history.toList()..sort((a,b)=>(b['lastOpenedAt']?.toString()??'').compareTo(a['lastOpenedAt']?.toString()??''));return Scaffold(appBar:AppBar(title:const Text('Saved'),actions:[IconButton(onPressed:()async{final name=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('New collection'),content:TextField(controller:name,decoration:const InputDecoration(labelText:'Collection name')),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Create'))]));if(ok==true&&name.text.trim().isNotEmpty){await c.save('collections',{'id':DateTime.now().microsecondsSinceEpoch.toString(),'name':name.text.trim(),'contentIds':<String>[],'createdAt':DateTime.now().toIso8601String()});}},icon:const Icon(Icons.create_new_folder_outlined))]),body:ListView(padding:const EdgeInsets.all(18),children:[const Text('Your saved guides, breeds and reading history stay on this device.'),const SizedBox(height:14),const Text('Favorites',style:TextStyle(fontWeight:FontWeight.w800,fontSize:19)),if(saved.isEmpty)const Padding(padding:EdgeInsets.symmetric(vertical:10),child:Text('Nothing saved yet. Bookmark a guide or breed to find it here.')),...saved.map((e)=>Card(child:ListTile(title:Text(e['title']?.toString()??e['contentId']?.toString()??'Saved item'),subtitle:Text(e['contentType']?.toString()??'Editorial content'),trailing:IconButton(icon:const Icon(Icons.bookmark_remove_outlined),onPressed:()=>c.delete('favorites',e['id'] as String))))),const SizedBox(height:18),const Text('Collections',style:TextStyle(fontWeight:FontWeight.w800,fontSize:19)),if(c.items('collections').isEmpty)const Text('Create a collection to group useful guides.'),...c.items('collections').map((e)=>Card(child:ListTile(title:Text(e['name']?.toString()??'Collection'),subtitle:Text('${(e['contentIds'] as List? ?? []).length} saved items'),onTap:()=>manageCollection(context,c,e),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>c.delete('collections',e['id'] as String))))),const SizedBox(height:18),const Text('Recently read',style:TextStyle(fontWeight:FontWeight.w800,fontSize:19)),if(history.isEmpty)const Text('Articles you open will appear here.'),...historySorted.take(10).map((e)=>ListTile(title:Text(e['title']?.toString()??'Article'),subtitle:Text(e['lastOpenedAt']==null?'':DateFormat.yMMMd().add_jm().format(DateTime.parse(e['lastOpenedAt'] as String))))) ]));}}

Future<void> manageCollection(BuildContext context,AppController controller,Map<String,dynamic> collection)async{final ids=(collection['contentIds'] as List? ?? []).map((e)=>e.toString()).toSet();await showModalBottomSheet<void>(context:context,isScrollControlled:true,builder:(ctx)=>StatefulBuilder(builder:(ctx,set)=>SafeArea(child:Padding(padding:const EdgeInsets.all(18),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text(collection['name']?.toString()??'Collection',style:Theme.of(ctx).textTheme.titleLarge),const SizedBox(height:8),if(controller.items('favorites').isEmpty)const Text('Save a guide or breed first.'),...controller.items('favorites').map((item){final id=item['id'] as String;return CheckboxListTile(value:ids.contains(id),title:Text(item['title']?.toString()??'Saved item'),subtitle:Text(item['contentType']?.toString()??''),onChanged:(v){set(()=>v==true?ids.add(id):ids.remove(id));controller.save('collections',{...collection,'contentIds':ids.toList()});}}),const SizedBox(height:8),FilledButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Done'))])))));}
